const currencySymbols = {
  CNY: "¥",
  USD: "US$",
  EUR: "€",
  GBP: "£",
  JPY: "¥",
};

function dictionaryRows(type) {
  return dictionaries.filter((row) => row.type === type && row.status !== "disabled");
}

function dictionaryLabel(type, code) {
  const value = String(code || "").trim();
  if (!value) {
    return "";
  }

  const row = dictionaryRows(type).find((item) => item.code === value);
  if (row) {
    return currentLang === "zh" ? row.name_zh || row.name_en || value : row.name_en || row.name_zh || value;
  }

  const fallback = fallbackDictionaryLabels[type]?.[value];
  if (fallback) {
    return fallback[currentLang] || fallback.en || value;
  }

  return value;
}

function localizedCondition(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "new") {
    return t("condition.new");
  }
  if (normalized === "used") {
    return t("condition.used");
  }
  return value || "";
}

function isUsedCondition(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return normalized === "used" || normalized === "二手" || normalized === "二手车";
}

function isUsedVehicle(vehicle) {
  return isUsedCondition(vehicle?.record?.condition);
}

function primaryVehicleItems() {
  return vehicles.filter((vehicle) => !isUsedVehicle(vehicle));
}

function usedVehicleItems() {
  return vehicles.filter(isUsedVehicle);
}

function formatNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    return String(value || "");
  }
  return new Intl.NumberFormat(currentLang === "zh" ? "zh-CN" : "en-US", {
    maximumFractionDigits: 0,
  }).format(number);
}

function formatMoney(value, currency) {
  const raw = String(value || "").trim();
  if (!raw) {
    return "";
  }
  const code = String(currency || "USD").trim().toUpperCase();
  const prefix = currencySymbols[code] || `${code} `;
  return `${prefix}${formatNumber(raw)}`;
}

function buildPrice(record) {
  const min = String(record.price_min || "").trim();
  const max = String(record.price_max || "").trim();
  const currency = String(record.currency || "USD").trim();

  if (min && max) {
    if (Number(min) === Number(max)) {
      return formatMoney(min, currency);
    }
    return `${formatMoney(min, currency)} - ${formatMoney(max, currency)}`;
  }

  if (min) {
    return t("price.from", { price: formatMoney(min, currency) });
  }

  return t("price.askQuote");
}

function getFirstImage(value) {
  const first = String(value || "")
    .split(";")
    .map((item) => item.trim())
    .find(Boolean);

  if (!first) {
    return "";
  }

  if (/^(https?:|data:|\.\/|\/)/i.test(first)) {
    return first;
  }

  return `./assets/${first}`;
}

function compact(values) {
  return values.filter((value) => String(value || "").trim()).map((value) => String(value).trim());
}

function localizedName(item) {
  if (currentLang === "zh" && item.nameZh) {
    return item.nameZh;
  }
  return item.nameEn || item.name || "";
}

function localizedDescription(item) {
  if (currentLang === "zh" && item.descriptionZh) {
    return item.descriptionZh;
  }
  return item.descriptionEn || item.description || "";
}

function mapImportedVehicle(record) {
  const condition = String(record.condition || "").trim();
  const vehicleType = String(record.vehicle_type || "").trim();
  const energy = String(record.energy_type || "").trim();
  const filterValue = vehicleType || energy || condition.toLowerCase() || "uncategorized";

  return {
    id: record.sku,
    name: compact([record.brand, record.model, record.trim]).join(" "),
    nameEn: record.title_en || record.name_en || compact([record.brand, record.model, record.trim]).join(" "),
    nameZh: record.title_zh || record.name_zh || "",
    descriptionEn: record.description_en || "",
    descriptionZh: record.description_zh || "",
    type: filterValue,
    filterValue,
    media: vehicleType || energy || condition || "vehicle",
    image: getFirstImage(record.images),
    record,
  };
}

function mapImportedPart(record) {
  const name = String(record.name || record.product_name || "").trim();
  const mark = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase();

  return {
    id: record.sku,
    name,
    nameEn: record.title_en || record.name_en || name,
    nameZh: record.title_zh || record.name_zh || "",
    descriptionEn: record.description_en || "",
    descriptionZh: record.description_zh || "",
    category: record.category || "other",
    filterValue: record.category || "other",
    oe: record.oe_numbers || record.part_number || "OE matching",
    fitment: compact([record.applicable_brand, record.applicable_model]).join(" / ") || "Model-specific",
    moq: record.moq || "Ask MOQ",
    lead: record.stock_status || (record.lead_time_days ? `${record.lead_time_days} days` : "Ask sales"),
    mark: mark || "AP",
    image: getFirstImage(record.images),
    record,
  };
}

function vehicleDisplay(vehicle) {
  const record = vehicle.record || {};
  const vehicleType = dictionaryLabel("vehicle_types", record.vehicle_type || vehicle.filterValue);
  const energy = dictionaryLabel("energy_types", record.energy_type);
  const stock = dictionaryLabel("stock_statuses", record.stock_status) || t("stock.askSales");
  const condition = localizedCondition(record.condition);
  const isUsed = isUsedVehicle(vehicle);

  return {
    badge: compact([condition, vehicleType || energy]).join(" / "),
    specs: compact([
      record.year,
      vehicleType,
      energy,
      record.steering,
      isUsed && record.mileage ? `${formatNumber(record.mileage)} km` : "",
      !isUsed && record.range_km ? `${formatNumber(record.range_km)} km` : "",
      stock,
    ]).slice(0, 4),
    price: buildPrice(record),
    stock,
    typeLabel: vehicleType || energy || vehicle.filterValue,
    energyLabel: energy,
    exportPortLabel: dictionaryLabel("export_ports", record.export_port),
  };
}

function partDisplay(part) {
  const record = part.record || {};
  return {
    category: dictionaryLabel("part_categories", record.category || part.filterValue) || part.category,
    lead: dictionaryLabel("stock_statuses", record.stock_status) || part.lead,
    price: buildPrice(record),
  };
}

function setMetricValue(name, value) {
  const node = document.querySelector(`[data-metric-value="${name}"]`);
  if (node) {
    node.textContent = value;
  }
}

function renderMetrics() {
  const vehicleBrands = new Set(vehicles.map((vehicle) => vehicle.record?.brand).filter(Boolean));
  setMetricValue("brands", formatNumber(vehicleBrands.size));
  setMetricValue("parts", formatNumber(parts.length));
  setMetricValue("vehicles", formatNumber(vehicles.length));
  setMetricValue("quoteTarget", "72h");
}

function activeVehicleFilter() {
  return document.querySelector("[data-vehicle-filter].active")?.dataset.vehicleFilter || "all";
}

function activeUsedVehicleFilter() {
  return document.querySelector("[data-used-vehicle-filter].active")?.dataset.usedVehicleFilter || "all";
}

function activePartFilter() {
  return document.querySelector("[data-part-filter].active")?.dataset.partFilter || "all";
}

function countItems(rows, field) {
  return rows.reduce((counts, row) => {
    const value = String(row[field] || "").trim();
    if (value) {
      counts.set(value, (counts.get(value) || 0) + 1);
    }
    return counts;
  }, new Map());
}

function filterButtonHtml(kind, value, label, count, active) {
  const attr =
    {
      vehicles: "data-vehicle-filter",
      usedVehicles: "data-used-vehicle-filter",
      parts: "data-part-filter",
    }[kind] || "data-vehicle-filter";
  return `<button class="filter-chip${active ? " active" : ""}" type="button" ${attr}="${escapeHtml(value)}">${escapeHtml(label)} <span>${escapeHtml(formatNumber(count))}</span></button>`;
}

function renderVehicleFilterControlsFor(rowSelector, kind, items, currentFilter) {
  const row = document.querySelector(rowSelector);
  if (!row) {
    return;
  }
  const counts = countItems(items, "filterValue");
  const current = counts.has(currentFilter) ? currentFilter : "all";
  const buttons = [filterButtonHtml(kind, "all", t("filter.all"), items.length, current === "all")];
  [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || dictionaryLabel("vehicle_types", a[0]).localeCompare(dictionaryLabel("vehicle_types", b[0])))
    .forEach(([value, count]) => {
      buttons.push(filterButtonHtml(kind, value, dictionaryLabel("vehicle_types", value), count, current === value));
    });
  row.innerHTML = buttons.join("");
}

function renderVehicleFilterControls() {
  renderVehicleFilterControlsFor("[data-vehicle-filters]", "vehicles", primaryVehicleItems(), activeVehicleFilter());
}

function renderUsedVehicleFilterControls() {
  renderVehicleFilterControlsFor("[data-used-vehicle-filters]", "usedVehicles", usedVehicleItems(), activeUsedVehicleFilter());
}

function renderPartFilterControls() {
  const row = document.querySelector("[data-part-filters]");
  if (!row) {
    return;
  }
  const counts = countItems(parts, "filterValue");
  const current = counts.has(activePartFilter()) ? activePartFilter() : "all";
  const buttons = [filterButtonHtml("parts", "all", t("filter.all"), parts.length, current === "all")];
  [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || dictionaryLabel("part_categories", a[0]).localeCompare(dictionaryLabel("part_categories", b[0])))
    .forEach(([value, count]) => {
      buttons.push(filterButtonHtml("parts", value, dictionaryLabel("part_categories", value), count, current === value));
    });
  row.innerHTML = buttons.join("");
}

function renderEnergyOptions() {
  const select = document.querySelector("[data-energy-select]");
  if (!select) {
    return;
  }
  const current = select.value;
  const energyCodes = [...new Set(vehicles.map((vehicle) => vehicle.record?.energy_type).filter(Boolean))].sort((a, b) =>
    dictionaryLabel("energy_types", a).localeCompare(dictionaryLabel("energy_types", b)),
  );
  select.innerHTML = [
    `<option value="">${escapeHtml(t("search.any"))}</option>`,
    ...energyCodes.map((code) => `<option value="${escapeHtml(code)}">${escapeHtml(dictionaryLabel("energy_types", code))}</option>`),
  ].join("");
  select.value = energyCodes.includes(current) ? current : "";
}

function renderFilterControls() {
  renderVehicleFilterControls();
  renderUsedVehicleFilterControls();
  renderPartFilterControls();
  renderEnergyOptions();
}

function loadVehicles() {
  return [];
}

function loadParts() {
  return [];
}

async function loadApiData() {
  if (location.protocol === "file:") {
    return;
  }

  try {
    const [vehicleResponse, partResponse, dictionaryResponse] = await Promise.all([
      fetch("/api/vehicles"),
      fetch("/api/parts"),
      fetch("/api/dictionaries"),
    ]);
    if (!vehicleResponse.ok || !partResponse.ok) {
      return;
    }

    const vehiclePayload = await vehicleResponse.json();
    const partPayload = await partResponse.json();
    const dictionaryPayload = dictionaryResponse.ok ? await dictionaryResponse.json() : { items: [] };
    dictionaries = Array.isArray(dictionaryPayload.items) ? dictionaryPayload.items : [];
    const apiVehicles = Array.isArray(vehiclePayload.items) ? vehiclePayload.items.map(mapImportedVehicle) : [];
    const apiParts = Array.isArray(partPayload.items) ? partPayload.items.map(mapImportedPart) : [];

    vehicles = apiVehicles;
    parts = apiParts;
    renderMetrics();
    renderFilterControls();
    renderVehicles(activeVehicleFilter());
    renderUsedVehicles(activeUsedVehicleFilter());
    renderParts(activePartFilter());
  } catch {
    // Keep the page empty when the backend is not running.
  }
}

let vehicles = loadVehicles();
let parts = loadParts();
let dictionaries = [];
const inquiryItems = new Map();
let activeSearchTab = "vehicles";
const searchState = {
  vehicles: { query: "", energy: "" },
  parts: { query: "", oe: "" },
};

const header = document.querySelector(".site-header");
const hero = document.querySelector(".hero");
const menuToggle = document.querySelector(".menu-toggle");
const vehicleGrid = document.querySelector("[data-vehicle-grid]");
const usedVehicleGrid = document.querySelector("[data-used-vehicle-grid]");
const partGrid = document.querySelector("[data-part-grid]");
const inquiryDrawer = document.querySelector("[data-inquiry-drawer]");
const detailDrawer = document.querySelector("[data-detail-drawer]");
const detailTitle = document.querySelector("[data-detail-title]");
const detailContent = document.querySelector("[data-detail-content]");
const inquiryItemsEl = document.querySelector("[data-inquiry-items]");
const toast = document.querySelector("[data-toast]");
const aiReception = document.querySelector("[data-ai-reception]");
const aiPanel = document.querySelector("[data-ai-panel]");
const aiMessagesEl = document.querySelector("[data-ai-messages]");
const aiForm = document.querySelector("[data-ai-form]");
const searchForm = document.querySelector("[data-search-form]");
const vehicleField = document.querySelector("[data-vehicle-field]");
const partField = document.querySelector("[data-part-field]");
