function textMatches(row, fields, query) {
  const needle = String(query || "").trim().toLowerCase();
  if (!needle) {
    return true;
  }
  return fields.some((field) => String(row[field] || "").toLowerCase().includes(needle));
}

function vehicleMatchesSearch(vehicle) {
  const record = vehicle.record || {};
  const criteria = searchState.vehicles;
  const matchesQuery = textMatches(
    {
      ...record,
      localized_name: localizedName(vehicle),
      vehicle_type_label: dictionaryLabel("vehicle_types", record.vehicle_type),
      energy_label: dictionaryLabel("energy_types", record.energy_type),
    },
    ["sku", "brand", "model", "trim", "title_en", "title_zh", "description_en", "description_zh", "localized_name", "vehicle_type_label", "energy_label"],
    criteria.query,
  );
  const matchesEnergy = !criteria.energy || record.energy_type === criteria.energy;
  return matchesQuery && matchesEnergy;
}

function partMatchesSearch(part) {
  const record = part.record || {};
  const criteria = searchState.parts;
  const matchesQuery = textMatches(
    {
      ...record,
      localized_name: localizedName(part),
      category_label: dictionaryLabel("part_categories", record.category),
    },
    ["sku", "name", "title_en", "title_zh", "description_en", "description_zh", "localized_name", "category_label", "applicable_brand", "applicable_model"],
    criteria.query,
  );
  const matchesOe = textMatches(record, ["oe_numbers", "part_number"], criteria.oe);
  return matchesQuery && matchesOe;
}

function renderVehicleList(grid, items, filter, emptyKey) {
  if (!grid) {
    return;
  }
  const filtered = (filter === "all" ? items : items.filter((vehicle) => vehicle.filterValue === filter)).filter(vehicleMatchesSearch);
  if (!filtered.length) {
    const empty = document.createElement("div");
    empty.className = "drawer-empty";
    empty.textContent = t(emptyKey);
    grid.replaceChildren(empty);
    return;
  }
  grid.replaceChildren(...filtered.map(makeVehicleCard));
}

function renderVehicles(filter = "all") {
  renderVehicleList(vehicleGrid, primaryVehicleItems(), filter, "vehicles.empty");
}

function renderUsedVehicles(filter = "all") {
  renderVehicleList(usedVehicleGrid, usedVehicleItems(), filter, "usedVehicles.empty");
}

function renderParts(filter = "all") {
  const filtered = (filter === "all" ? parts : parts.filter((part) => part.filterValue === filter)).filter(partMatchesSearch);
  if (!filtered.length) {
    const empty = document.createElement("div");
    empty.className = "drawer-empty";
    empty.textContent = t("parts.empty");
    partGrid.replaceChildren(empty);
    return;
  }
  partGrid.replaceChildren(...filtered.map(makePartCard));
}

function getProductById(id) {
  const vehicle = vehicles.find((item) => item.id === id);
  if (vehicle) {
    const display = vehicleDisplay(vehicle);
    return { id, kind: "Vehicle", name: localizedName(vehicle), meta: `${display.typeLabel} | ${display.stock}` };
  }

  const part = parts.find((item) => item.id === id);
  if (part) {
    const display = partDisplay(part);
    return { id, kind: "Auto Part", name: localizedName(part), meta: `${display.category} | ${part.oe}` };
  }

  return null;
}

function renderInquiryItems() {
  const items = [...inquiryItems.values()];
  if (!items.length) {
    inquiryItemsEl.innerHTML = `<div class="drawer-empty">${escapeHtml(t("drawer.empty"))}</div>`;
    return;
  }

  inquiryItemsEl.replaceChildren(
    ...items.map((item) => {
      const el = document.createElement("div");
      el.className = "drawer-item";
      const itemName = escapeHtml(item.name);
      const itemId = escapeHtml(item.id);
      el.innerHTML = `
        <div>
          <strong>${itemName}</strong>
          <span>${escapeHtml(item.kind)} | ${escapeHtml(item.meta)}</span>
        </div>
        <button type="button" aria-label="Remove ${itemName}" data-remove-inquiry="${itemId}">x</button>
      `;
      return el;
    }),
  );
}

function openInquiry() {
  renderInquiryItems();
  inquiryDrawer.setAttribute("aria-hidden", "false");
  document.body.classList.add("drawer-open");
}

function closeInquiry() {
  inquiryDrawer.setAttribute("aria-hidden", "true");
  document.body.classList.remove("drawer-open");
}

function findProduct(id) {
  const vehicle = vehicles.find((item) => item.id === id);
  if (vehicle) {
    return { kind: "Vehicle", item: vehicle };
  }
  const part = parts.find((item) => item.id === id);
  if (part) {
    return { kind: "Auto Part", item: part };
  }
  return null;
}

function specBlock(label, value) {
  if (!String(value || "").trim()) {
    return "";
  }
  return `
    <div>
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

function renderDetail(product) {
  const { kind, item } = product;
  const isVehicle = kind === "Vehicle";
  const record = item.record || {};
  const title = localizedName(item);
  const description = localizedDescription(item) || t("detail.descriptionFallback");
  const vehicleInfo = isVehicle ? vehicleDisplay(item) : null;
  const partInfo = isVehicle ? null : partDisplay(item);
  const specs = isVehicle
    ? [
        [t("detail.vehicleType"), vehicleInfo.typeLabel],
        [t("detail.energyType"), vehicleInfo.energyLabel],
        [t("detail.year"), record.year || item.specs?.[0]],
        [t("detail.mileage"), record.mileage ? `${formatNumber(record.mileage)} km` : ""],
        [t("detail.registrationDate"), record.registration_date],
        [t("detail.currentLocation"), record.location],
        [t("detail.emissionStandard"), record.emission_standard],
        [t("detail.steering"), record.steering || ""],
        [t("detail.stockStatus"), vehicleInfo.stock],
        [t("detail.price"), vehicleInfo.price],
        [t("detail.exportPort"), vehicleInfo.exportPortLabel],
        [t("detail.inspectionReport"), record.inspection_report],
        [t("detail.accidentNote"), record.accident_note],
      ]
    : [
        [t("parts.title"), partInfo.category],
        [t("detail.oeNumber"), record.oe_numbers || item.oe],
        [t("detail.fitment"), compact([record.applicable_brand, record.applicable_model]).join(" / ") || item.fitment],
        [t("detail.moq"), record.moq || item.moq],
        [t("detail.leadTime"), record.lead_time_days ? `${record.lead_time_days} days` : partInfo.lead],
        [t("detail.price"), partInfo.price],
      ];

  detailTitle.textContent = title;
  detailContent.innerHTML = `
    <div class="detail-visual ${item.image ? "has-image" : ""}"></div>
    <div class="detail-summary">
      <h3>${escapeHtml(title)}</h3>
      <p>${escapeHtml(description)}</p>
    </div>
    <div>
      <p class="eyebrow">${escapeHtml(t("detail.specifications"))}</p>
      <div class="detail-specs">
        ${specs.map(([label, value]) => specBlock(label, value)).join("")}
      </div>
    </div>
    <div class="detail-actions">
      <button class="solid-button" type="button" data-add-inquiry="${escapeHtml(item.id)}" data-kind="${escapeHtml(kind)}">${escapeHtml(t("detail.addInquiry"))}</button>
      <button class="ghost-button" type="button" data-open-inquiry>${escapeHtml(t("detail.contact"))}</button>
    </div>
  `;
  setBackgroundImage(detailContent.querySelector(".detail-visual"), item.image);
}

function openDetail(id) {
  const product = findProduct(id);
  if (!product) {
    return;
  }
  renderDetail(product);
  detailDrawer.dataset.currentProductId = id;
  detailDrawer.setAttribute("aria-hidden", "false");
  document.body.classList.add("drawer-open");
}

function closeDetail() {
  detailDrawer.setAttribute("aria-hidden", "true");
  detailDrawer.dataset.currentProductId = "";
  document.body.classList.remove("drawer-open");
}

async function submitInquiry(payload) {
  if (location.protocol === "file:") {
    return false;
  }

  try {
    const response = await fetch("/api/inquiries", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        ...payload,
        source_url: location.href,
      }),
    });
    return response.ok;
  } catch {
    return false;
  }
}

function setActiveChip(chip, selector) {
  document.querySelectorAll(selector).forEach((item) => item.classList.remove("active"));
  chip.classList.add("active");
}

function setSearchTab(tab) {
  activeSearchTab = tab;
  document.querySelectorAll("[data-search-tab]").forEach((button) => {
    button.classList.toggle("active", button.dataset.searchTab === tab);
  });
  vehicleField.hidden = tab !== "vehicles";
  partField.hidden = tab !== "parts";
  primaryLabel.textContent = tab === "vehicles" ? t("search.brandModel") : t("search.partName");
}

document.addEventListener("click", (event) => {
  const target = event.target;

  if (target.closest("[data-ai-toggle]")) {
    openAiReception();
    return;
  }

  if (target.closest("[data-ai-close]")) {
    closeAiReception();
    return;
  }

  const vehicleFilter = target.closest("[data-vehicle-filter]");
  if (vehicleFilter) {
    setActiveChip(vehicleFilter, "[data-vehicle-filter]");
    renderVehicles(vehicleFilter.dataset.vehicleFilter);
    return;
  }

  const usedVehicleFilter = target.closest("[data-used-vehicle-filter]");
  if (usedVehicleFilter) {
    setActiveChip(usedVehicleFilter, "[data-used-vehicle-filter]");
    renderUsedVehicles(usedVehicleFilter.dataset.usedVehicleFilter);
    return;
  }

  const partFilter = target.closest("[data-part-filter]");
  if (partFilter) {
    setActiveChip(partFilter, "[data-part-filter]");
    renderParts(partFilter.dataset.partFilter);
    return;
  }

  const searchTab = target.closest("[data-search-tab]");
  if (searchTab) {
    setSearchTab(searchTab.dataset.searchTab);
    return;
  }

  const addButton = target.closest("[data-add-inquiry]");
  if (addButton) {
    const product = getProductById(addButton.dataset.addInquiry);
    if (product) {
      inquiryItems.set(product.id, product);
      renderInquiryItems();
      showToast(`${product.name} ${t("toast.added")}`);
    }
    return;
  }

  if (target.closest("[data-open-inquiry]")) {
    closeDetail();
    openInquiry();
    return;
  }

  if (target.closest("[data-close-inquiry]")) {
    closeInquiry();
    return;
  }

  const detailButton = target.closest("[data-open-detail]");
  if (detailButton) {
    openDetail(detailButton.dataset.openDetail);
    return;
  }

  if (target.closest("[data-close-detail]")) {
    closeDetail();
    return;
  }

  const removeButton = target.closest("[data-remove-inquiry]");
  if (removeButton) {
    inquiryItems.delete(removeButton.dataset.removeInquiry);
    renderInquiryItems();
    return;
  }

  if (target === inquiryDrawer) {
    closeInquiry();
  }

  if (target === detailDrawer) {
    closeDetail();
  }
});

menuToggle.addEventListener("click", () => {
  const expanded = menuToggle.getAttribute("aria-expanded") === "true";
  menuToggle.setAttribute("aria-expanded", String(!expanded));
  header.classList.toggle("nav-active", !expanded);
  document.body.classList.toggle("nav-open", !expanded);
});

document.querySelectorAll(".main-nav a").forEach((link) => {
  link.addEventListener("click", () => {
    menuToggle.setAttribute("aria-expanded", "false");
    header.classList.remove("nav-active");
    document.body.classList.remove("nav-open");
  });
});

searchForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const data = new FormData(searchForm);
  const keyword = String(data.get("keyword") || "").trim();
  const target = activeSearchTab === "vehicles" ? "#vehicles" : "#parts";
  if (activeSearchTab === "vehicles") {
    searchState.vehicles.query = keyword;
    searchState.vehicles.energy = String(data.get("energy") || "").trim();
    renderVehicles(activeVehicleFilter());
    renderUsedVehicles(activeUsedVehicleFilter());
  } else {
    searchState.parts.query = keyword;
    searchState.parts.oe = String(data.get("oe") || "").trim();
    renderParts(activePartFilter());
  }
  document.querySelector(target).scrollIntoView({ behavior: "smooth", block: "start" });
  showToast(
    keyword || data.get("energy") || data.get("oe")
      ? t("toast.searchMatches", { type: activeSearchTab === "vehicles" ? t("nav.vehicles") : t("nav.parts") })
      : t("toast.showingAvailable", { type: activeSearchTab === "vehicles" ? t("nav.vehicles") : t("nav.parts") }),
  );
});

document.querySelector("[data-contact-form]").addEventListener("submit", async (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const saved = await submitInquiry({
    name: data.get("name"),
    email: data.get("email"),
    country: data.get("country"),
    whatsapp: data.get("whatsapp"),
    message: data.get("message"),
    product_type: "General",
  });
  form.reset();
  showToast(saved ? t("toast.contactBackend") : t("toast.contactPrototype"));
});

document.querySelector("[data-drawer-form]").addEventListener("submit", async (event) => {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const items = [...inquiryItems.values()];
  const saved = await submitInquiry({
    name: data.get("email"),
    email: data.get("email"),
    country: data.get("destination"),
    message: data.get("message") || `Selected products: ${items.map((item) => item.name).join(", ")}`,
    product_type: items.some((item) => item.kind === "Vehicle") && items.some((item) => item.kind === "Auto Part") ? "Mixed" : items[0]?.kind || "General",
    items,
  });
  form.reset();
  inquiryItems.clear();
  renderInquiryItems();
  closeInquiry();
  showToast(saved ? t("toast.drawerBackend") : t("toast.drawerPrototype"));
});

if (aiForm) {
  aiForm.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (aiBusy) {
      return;
    }

    const textarea = aiForm.querySelector("textarea");
    const message = String(textarea?.value || "").trim();
    if (!message) {
      return;
    }

    textarea.value = "";
    await submitAiMessage(message);
  });
}

document.querySelector("[data-lang-toggle]").addEventListener("click", () => {
  currentLang = currentLang === "zh" ? "en" : "zh";
  localStorage.setItem("site_lang", currentLang);
  applyLanguage();
  renderFilterControls();
  renderVehicles(document.querySelector("[data-vehicle-filter].active")?.dataset.vehicleFilter || "all");
  renderUsedVehicles(document.querySelector("[data-used-vehicle-filter].active")?.dataset.usedVehicleFilter || "all");
  renderParts(document.querySelector("[data-part-filter].active")?.dataset.partFilter || "all");
  renderInquiryItems();
  if (detailDrawer.getAttribute("aria-hidden") === "false" && detailDrawer.dataset.currentProductId) {
    openDetail(detailDrawer.dataset.currentProductId);
  }
});

window.addEventListener("scroll", elevateHeader, { passive: true });
window.addEventListener("resize", elevateHeader, { passive: true });
window.addEventListener("hashchange", () => window.requestAnimationFrame(elevateHeader));
window.addEventListener("load", () => window.requestAnimationFrame(elevateHeader));

applyLanguage();
renderFilterControls();
renderVehicles();
renderUsedVehicles();
renderParts();
renderInquiryItems();
elevateHeader();
loadApiData();
